func TestOptionalNullableRoundTripW2(t *testing.T) {
	optionalNullableKeys := []string{
		"tax_year",
		"employer_id_number",
		"wages_tips_other_comp",
		"federal_income_tax_withheld",
		"social_security_wages",
		"social_security_tax_withheld",
		"medicare_wages_and_tips",
		"medicare_tax_withheld",
		"social_security_tips",
		"allocated_tips",
		"box_9",
		"dependent_care_benefits",
		"nonqualified_plans",
		"statutory_employee",
		"retirement_plan",
		"third_party_sick_pay",
		"other",
	}
	marshalToMap := func(t *testing.T, obj *W2) map[string]json.RawMessage {
		data, err := json.Marshal(obj)
		require.NoError(t, err, "marshaling should succeed")
		var result map[string]json.RawMessage
		require.NoError(t, json.Unmarshal(data, &result), "marshaled data should be a JSON object")
		return result
	}

	t.Run("NullPreserved", func(t *testing.T) {
		t.Parallel()
		var obj W2
		require.NoError(t, json.Unmarshal([]byte(`{"tax_year":null,"employer_id_number":null,"wages_tips_other_comp":null,"federal_income_tax_withheld":null,"social_security_wages":null,"social_security_tax_withheld":null,"medicare_wages_and_tips":null,"medicare_tax_withheld":null,"social_security_tips":null,"allocated_tips":null,"box_9":null,"dependent_care_benefits":null,"nonqualified_plans":null,"statutory_employee":null,"retirement_plan":null,"third_party_sick_pay":null,"other":null}`), &obj))
		result := marshalToMap(t, &obj)
		for _, key := range optionalNullableKeys {
			value, ok := result[key]
			require.True(t, ok, "optional nullable field %q received as null should be present in the output", key)
			assert.Equal(t, "null", string(value), "optional nullable field %q received as null should be null in the output", key)
		}
	})

	t.Run("AbsentStaysAbsent", func(t *testing.T) {
		t.Parallel()
		var obj W2
		require.NoError(t, json.Unmarshal([]byte(`{}`), &obj))
		result := marshalToMap(t, &obj)
		for _, key := range optionalNullableKeys {
			assert.NotContains(t, result, key, "optional nullable field %q absent from the input should be absent from the output", key)
		}
	})

	t.Run("FreshValueOmits", func(t *testing.T) {
		t.Parallel()
		result := marshalToMap(t, &W2{})
		for _, key := range optionalNullableKeys {
			assert.NotContains(t, result, key, "optional nullable field %q should be omitted from a freshly constructed value", key)
		}
	})
}

